        array['MYP 5', 'Mathematics', 'IB eAssessment', 'Standard', 'May 2025', 'ib-myp5-mathematics-standard-may-2025']::text[],
        'published', '{"question_number": "Question 6(f)", "paper_question": 6, "part_label": "Question 6(f)", "marks": 2, "calculator": true, "calculator_policy": "on_screen_only", "assessment_style": "ib_myp_eassessment", "source": "ib-myp5-mathematics-standard-may-2025", "parts": [{"id": "f", "label": "(f)", "kind": "numeric", "points": 2, "prompt": "Percentage increase of E", "answer": 21, "tolerance": 0.05, "unit": "%", "placeholder": "percentage", "hints": ["E depends on d², so scale d by 1.1 and see what happens to d².", "1.1² = 1.21, so E becomes 121 % of its original value."]}], "marks_status": "verified", "marks_note": "2 marks printed by the paper."}'::jsonb,
        '3c3ed712-f409-4aa1-a645-816418e22ec4', 'MYP', 'MYP 5 Mathematics', '0a400000-0000-4000-8000-000000000030',
        'approved', 'manual', '0a400000-0000-4000-8000-000000000107', 'ib-myp5-mathematics-standard-may-2025')
